guidance.correct_example:
def process(a_data: dict) -> Result[str]:
    b_continue = True
    result: Result[str] = INVALID_RESULT
    if not a_data:
        result = Result.failure('Empty data')
        b_continue = False
    if b_continue:
        result = Result.success(a_data.get('name', ''))
    return result

guidance.incorrect_example:
def process(a_data: dict) -> Result[str]:
    if not a_data:
        return Result.failure('Empty data')
    name = a_data.get('name', '')
    if not name:
        return Result.failure('Missing name')
    return Result.success(name)
